package io.github.diodeme.ji.spring;

import io.github.diodeme.ji.cli.LocalHostApplication;
import java.net.URI;

final class CliBackedJiHost implements JiHost {
    private final LocalHostApplication delegate;

    CliBackedJiHost(LocalHostApplication delegate) {
        this.delegate = delegate;
    }

    @Override public URI launchUri() { return delegate.launchUri(); }
    @Override public URI healthUri() { return delegate.healthUri(); }
    @Override public int port() { return delegate.port(); }
    @Override public int hcpPort() { return delegate.hcpPort(); }
    @Override public void close() { delegate.close(); }
}
